GO = json.loads('\x7b\x7d')
REFS = json.loads('[]')
DERIVE = json.loads('[\x7b"name":"kind","op":"first_of","items":[\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"-"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"_"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"0"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"1"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"2"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"3"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"4"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"5"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"6"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"7"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"8"\x7d],"text":"long"\x7d,\x7b"when":[\x7b"path":"data.ttsEmail","op":"contains","value":"9"\x7d],"text":"long"\x7d],"default":"plain"\x7d]')
OK_TEXT = json.loads('"The service answered. Continue the procedure with these values; say only what the procedure tells you to say."')
