        config['method'] = METHOD
    config['url'] = url
    h = config.get('headers')
    if not isinstance(h, dict):
        h = dict()
    for k in headers:
        h[k] = headers[k]
    config['headers'] = h
    if config['method'] in ('GET', 'HEAD', 'DELETE') and not body:
        config['body'] = None
    else:
        config['body'] = body
except Exception:
    pass

