DERIVE = json.loads('[\x7b"name":"last4","op":"spell_digits","a":"@statement_week_get.data.cardNumberLast4","names":["s\\u0131f\\u0131r","bir","iki","\\u00fc\\u00e7","d\\u00f6rt","be\\u015f","alt\\u0131","yedi","sekiz","dokuz"]\x7d,\x7b"name":"new_date","op":"format_date","a":"@statement_week_decide.data.statementDate","pattern":"D MMMM YYYY","months":["Ocak","\\u015eubat","Mart","Nisan","May\\u0131s","Haziran","Temmuz","A\\u011fustos","Eyl\\u00fcl","Ekim","Kas\\u0131m","Aral\\u0131k"]\x7d,\x7b"name":"new_due","op":"format_date","a":"@statement_week_decide.data.statementDueDate","pattern":"D MMMM YYYY","months":["Ocak","\\u015eubat","Mart","Nisan","May\\u0131s","Haziran","Temmuz","A\\u011fustos","Eyl\\u00fcl","Ekim","Kas\\u0131m","Aral\\u0131k"]\x7d,\x7b"name":"week_word","op":"first_of","items":[\x7b"when":[\x7b"path":"data.statementWeek","op":"eq","value":"1"\x7d],"text":"birinci"\x7d,\x7b"when":[\x7b"path":"data.statementWeek","op":"eq","value":"2"\x7d],"text":"ikinci"\x7d,\x7b"when":[\x7b"path":"data.statementWeek","op":"eq","value":"3"\x7d],"text":"\\u00fc\\u00e7\\u00fcnc\\u00fc"\x7d,\x7b"when":[\x7b"path":"data.statementWeek","op":"eq","value":"4"\x7d],"text":"d\\u00f6rd\\u00fcnc\\u00fc"\x7d],"default":"se\\u00e7ti\\u011finiz"\x7d]')
