            if 200 <= int(sc or 0) < 300:
                vars[TOOL + '_json'] = json.dumps(d, ensure_ascii=False)[:60000]
            vars[TOOL + '_state'] = 'ok' if 200 <= int(sc or 0) < 300 else 'error'
