        cents = int(round(abs(x) * 100))
        out = ('-' if x < 0 else '') + _fmt_num(cents // 100, '', str(r.get('thousands', '')), 0) + ' ' + str(r.get('unit') or '')
        if cents % 100 and r.get('subunit'):
