def _fmt_num(x, dec, tho, places):
    s = ('%.' + str(places) + 'f') % abs(x)
    whole, frac = (s.split('.') + [''])[:2]
    groups = []
    while len(whole) > 3:
        groups.insert(0, whole[-3:])
        whole = whole[:-3]
    groups.insert(0, whole)
    return ('-' if x < 0 else '') + tho.join(groups) + ((dec + frac) if places else '')

def _derive_one(d, r, today):
    op = str(r.get('op') or '')
