        x, y = _num(a), _num(b)
        if x is None or y is None:
            return None
        if op == 'compare':
            return 'less' if x < y else ('equal' if x == y else 'greater')
        v = x + y if op == 'add' else x - y if op == 'sub' else x * y if op == 'mul' else (x / y if y else None) if op == 'div' else min(x, y) if op == 'min' else max(x, y)
