PARAMS = json.loads('[["data_customerno","body","string","data.customerNo"],["data_intaddressinfotype","body","string","data.intAddressInfoType"],["call_lang","body","string","call.lang"]]')
SNAP = json.loads('[]')
TOOL = json.loads('"contact_email"')
APART = json.loads('[]')
